from functools import lru_cache

@lru_cache(maxsize=None)
def fibonacci(n: int) -> int:
    if n <= 1: return n
    return fibonacci(n-1) + fibonacci(n-2)

With memoization: O(n) time, O(n) space. Without: O(2^n) time.

def lcs(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0]*(n+1) for _ in range(m+1)]
    for i in range(1, m+1):
        for j in range(1, n+1):
            if s1[i-1] == s2[j-1]: dp[i][j] = dp[i-1][j-1]+1
            else: dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[m][n]

Time: O(mn), Space: O(mn).

function debounce(fn, delay) {
  let timer;
  return function(...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

Debouncing ensures fn is called only after the caller has stopped invoking it for 'delay' ms.

class ApiClient {
  constructor(private baseUrl: string) {}
  async get<T>(path: string): Promise<T> {
    const res = await fetch(`${this.baseUrl}${path}`);
    return res.json();
  }
  async post<T>(path: string, body: unknown): Promise<T> {
    const res = await fetch(`${this.baseUrl}${path}`, {
      method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(body)
    });
    return res.json();
  }
}

from flask import Flask, request, jsonify
app = Flask(__name__)

@app.route('/wordcount', methods=['POST'])
def word_count():
    data = request.get_json()
    text = data.get('text', '')
    count = len(text.split())
    return jsonify({'word_count': count})

Request: POST /wordcount {"text": "hello world"} → Response: {"word_count": 2}

def dfs(graph, start, visited=None):
    if visited is None: visited = set()
    visited.add(start)
    for neighbor in graph[start]:
        if neighbor not in visited:
            dfs(graph, neighbor, visited)
    return visited

Time: O(V+E), Space: O(V). Uses recursion and a visited set to avoid cycles.
